<section class="mt-7"><h2 class="text-xl font-extrabold">Payment gateways</h2><p class="text-sm text-[#78908c]">Configure billing mode and public identifiers. Secret keys remain server-managed.</p></section>
<section class="mt-6 grid gap-4 lg:grid-cols-3"><?php foreach(['stripe'=>'Stripe','razorpay'=>'Razorpay','paypal'=>'PayPal'] as$key=>$label): ?><?php $row=null;foreach($gateways as$g)if($g['gateway']===$key)$row=$g; ?><form action="<?= base_url('admin/payments') ?>" method="post" class="card p-5"><?= csrf_field() ?><input type="hidden" name="gateway" value="<?= $key ?>"><h3 class="font-extrabold"><?= $label ?></h3><select name="mode" class="field mt-4"><option value="test" <?= ($row['mode']??'')==='test'?'selected':'' ?>>Test mode</option><option value="live" <?= ($row['mode']??'')==='live'?'selected':'' ?>>Live mode</option></select><input name="public_key" value="<?= esc($row['public_key']??'') ?>" class="field mt-3" placeholder="Public / publishable key"><input name="currency" value="<?= esc($row['currency']??'USD') ?>" class="field mt-3" maxlength="3"><label class="mt-3 flex gap-2 text-sm"><input type="checkbox" name="enabled" value="1" <?= ($row['enabled']??0)?'checked':'' ?>> Enabled</label><button class="btn btn-primary mt-4">Save</button></form><?php endforeach ?></section>
